use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn generate_semantic_groups (secretome : & mut SemanticSecretome) { let mut compiler_core = Vec :: new () ; let mut memory_mgmt = Vec :: new () ; let mut io_network = Vec :: new () ; let mut parsing_ast = Vec :: new () ; let mut crypto_hash = Vec :: new () ; let mut error_handling = Vec :: new () ; for key in secretome . functions . keys () . chain (secretome . types . keys ()) . chain (secretome . constants . keys ()) { let lower_key = key . to_lowercase () ; if lower_key . contains ("rustc") || lower_key . contains ("compiler") || lower_key . contains ("codegen") { compiler_core . push (key . clone ()) ; } else if lower_key . contains ("alloc") || lower_key . contains ("memory") || lower_key . contains ("heap") { memory_mgmt . push (key . clone ()) ; } else if lower_key . contains ("io") || lower_key . contains ("net") || lower_key . contains ("http") { io_network . push (key . clone ()) ; } else if lower_key . contains ("parse") || lower_key . contains ("ast") || lower_key . contains ("syn") { parsing_ast . push (key . clone ()) ; } else if lower_key . contains ("hash") || lower_key . contains ("crypto") || lower_key . contains ("sha") { crypto_hash . push (key . clone ()) ; } else if lower_key . contains ("error") || lower_key . contains ("result") || lower_key . contains ("panic") { error_handling . push (key . clone ()) ; } } secretome . semantic_groups . insert ("compiler_core" . to_string () , compiler_core) ; secretome . semantic_groups . insert ("memory_management" . to_string () , memory_mgmt) ; secretome . semantic_groups . insert ("io_network" . to_string () , io_network) ; secretome . semantic_groups . insert ("parsing_ast" . to_string () , parsing_ast) ; secretome . semantic_groups . insert ("crypto_hash" . to_string () , crypto_hash) ; secretome . semantic_groups . insert ("error_handling" . to_string () , error_handling) ; }
}